 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.recipe_group_id<>g OR r.language<>'es' OR r.slug<>b->>'slug' OR r.public_path<>b->>'public_path'
    OR r.source_url IS DISTINCT FROM b->>'source_url' OR r.created_at<>(b->>'created_at')::timestamptz
    OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Historical identity/date divergence before idempotent or initial publication';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j)x WHERE (x->>'recipe_group_id')::uuid<>g
    OR x->>'language' NOT IN ('es','de','en','fr','it','ja','pt')) THEN
  RAISE EXCEPTION 'Unexpected group or language in publication payload';
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)=7
  AND NOT EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR NOT r.published OR r.editorial_status<>'published' OR r.recipe_group_id<>x.recipe_group_id
      OR r.language<>x.language OR r.slug<>x.slug OR r.public_path<>x.public_path OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE NOTICE 'Bean salad with romesco already matches7/7; no mutation'; RETURN;
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>1
  OR NOT EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND r.recipe_group_id=g
    AND r.language='es' AND NOT r.published AND md5(to_jsonb(r)::text)=b->>'expected_row_md5') THEN
  RAISE EXCEPTION 'Reserved beanromesco state changed; reconcile before retry';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON r.id=x.id OR r.public_path=x.public_path OR (r.language=x.language AND r.slug=x.slug)
  WHERE r.id<>x.id OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language) THEN
  RAISE EXCEPTION 'Bean salad with romesco recipe identity/route collision';
 END IF;
 IF EXISTS(SELECT 1 FROM public.content_pages c JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON c.public_path=x.public_path OR (c.language=x.language AND c.slug=x.slug)) THEN
  RAISE EXCEPTION 'Bean salad with romesco content_page route collision';
 END IF;
 SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) INTO outside_checksum
  FROM public.recipes r WHERE r.recipe_group_id<>g;
 SELECT count(*) INTO es_count FROM public.recipes WHERE language='es' AND published;
 UPDATE public.recipes r SET title=x.title, excerpt=x.excerpt, summary=x.summary, ingredients=x.ingredients, steps=x.steps, category=x.category, prep_time_minutes=x.prep_time_minutes, cook_time_minutes=x.cook_time_minutes, total_time_minutes=x.total_time_minutes, servings=x.servings, image_url=x.image_url, content_html=x.content_html, notes=x.notes, difficulty=x.difficulty, course=x.course, cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,editorial_status='published',ready_at=now(),published=true
  FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE r.id=x.id AND x.language='es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Expected1ES update, got%',n; END IF;
 INSERT INTO public.recipes(id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published) SELECT x.id,x.recipe_group_id,x.language,x.slug,x.public_path,x.source_url,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,x.content_html,x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',now(),true FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE x.language<>'es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>6 THEN RAISE EXCEPTION 'Expected6translations, got%',n; END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>7
  OR (SELECT count(DISTINCT language) FROM public.recipes WHERE recipe_group_id=g AND published AND editorial_status='published')<>7
  OR EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language
      OR r.slug<>x.slug OR r.public_path<>x.public_path OR NOT r.published OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE EXCEPTION 'Bean salad with romesco7/7 final content verification failed';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.slug<>b->>'slug' OR r.public_path<>b->>'public_path' OR r.source_url IS DISTINCT FROM b->>'source_url'
    OR r.created_at<>(b->>'created_at')::timestamptz OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Bean salad with romesco historical identity/date preservation failed';
 END IF;
 IF outside_checksum IS DISTINCT FROM(SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) FROM public.recipes r WHERE r.recipe_group_id<>g)
  OR (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>es_count+1 THEN
  RAISE EXCEPTION 'Unexpected change outside beanromesco group';
 END IF;
 RAISE NOTICE 'Bean salad with romesco verified7/7 within surrounding atomic lote04 transaction';
END
$beanromesco$;

-- Prepared seven-language gingercookies block; NOT executed.
-- Integrate inside one atomic15recipe lote04 transaction ONLY after all15ready,
-- CI/merge and observed deployed media hashes. Caller must set the batch gate.
DO $gingercookies$
DECLARE
 j constant jsonb := $records$[{"id": "670af688-3058-4f8c-9070-96eaae0bda4f", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "receta-de-galletas-de-jengibre", "public_path": "/receta-de-galletas-de-jengibre", "source_url": "https://manualdecocina.com/receta-de-galletas-de-jengibre/", "language": "es", "title": "Galletas redondas de jengibre y melaza", "excerpt": "Galletas de jengibre seco y melaza sin glaseado, con cantidades pesadas, frío y dos tandas de horno para 24 unidades propuestas.", "summary": "Galletas redondas propuestas de jengibre seco, canela y melaza, sin glaseado. Se reparte toda la masa en 24 porciones y se incluyen frío, dos tandas de horno y enfriado: 159 minutos propuestos, pendientes de confirmación en cocina.", "category": "Postres", "category_slug": "postres", "difficulty": "Media", "course": "Postre", "cuisine": "Inspiración europea", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "harina de trigo común, sin levadura incorporada", "amount": "300", "unit": "g", "group": "Secos"}, {"name": "jengibre molido seco", "amount": "6", "unit": "g", "group": "Secos"}, {"name": "canela molida", "amount": "3", "unit": "g", "group": "Secos"}, {"name": "bicarbonato sódico alimentario", "amount": "3", "unit": "g", "group": "Secos"}, {"name": "sal fina", "amount": "2", "unit": "g", "group": "Secos"}, {"name": "mantequilla sin sal", "amount": "100", "unit": "g", "group": "Húmedos"}, {"name": "azúcar moreno", "amount": "80", "unit": "g", "group": "Húmedos"}, {"name": "melaza de caña para uso alimentario", "amount": "100", "unit": "g", "group": "Húmedos"}, {"name": "huevo entero batido, peso sin cáscara", "amount": "50", "unit": "g", "group": "Húmedos"}], "steps": [{"title": "Pesa y organiza", "content": "Lávate las manos y prepara báscula, dos bandejas de unos 40 × 30 cm con papel de horno, batidora, espátula y rejilla. Pesa 300 g de harina, 6 g de jengibre, 3 g de canela, 3 g de bicarbonato, 2 g de sal, 100 g de mantequilla, 80 g de azúcar moreno y 100 g de melaza. Bate el huevo en un cuenco y pesa 50 g sin cáscara. Deja la mantequilla unos 20 minutos hasta que ceda a la presión sin fundirse; dedica unos 10 de esos minutos a pesar y organizar. Mantén el huevo en frío hasta usarlo. No pruebes harina ni masa cruda.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "Galletas de jengibre y melaza: Pesa y organiza"}, {"title": "Bate los húmedos", "content": "Bate la mantequilla blanda con el azúcar moreno hasta que no queden grumos grandes. Añade la melaza y el huevo pesado; mezcla y raspa con la batidora apagada hasta integrar. Dedica unos 5 minutos en total. No añadas miel, agua, vainilla ni más huevo: esta fórmula y su cálculo solo incluyen los ingredientes pesados.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "Galletas de jengibre y melaza: Bate los húmedos"}, {"title": "Une los secos y forma la masa", "content": "Mezcla aparte toda la harina, el jengibre, la canela, el bicarbonato y la sal, deshaciendo grumos. Incorpora a los húmedos con espátula hasta que no se vea harina seca, sin amasar prolongadamente. Dedica unos 5 minutos. La masa será pegajosa; no corrijas con harina extra. Si queda harina suelta, raspa y sigue integrando; cualquier cambio de cantidad exige revisar el cálculo.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "Galletas de jengibre y melaza: Une los secos y forma la masa"}, {"title": "Divide y enfría", "content": "Divide toda la masa en 24 porciones iguales en unos 5 minutos; los 644 g iniciales equivalen a unos 26,8 g por porción antes de hornear, no a un peso final medido. Forma bolas con manos limpias, ponlas en un recipiente, tapa y refrigera a 4 °C o menos durante 60 minutos, hasta que estén firmes. Precalienta el horno a 175 °C con calor arriba y abajo durante los últimos 15 minutos de ese frío. Si hace falta enfriar más, suma el tiempo real.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "Galletas de jengibre y melaza: Divide y enfría"}, {"title": "Aplana sin añadir cobertura", "content": "Reparte 12 bolas en cada bandeja, en una cuadrícula de 4 × 3. Aplana entre pequeños trozos de papel de horno con una base plana hasta discos de unos 6 cm de diámetro y 1 cm de grosor; deja unos 3 cm entre bordes y retira el papel superior. Dedica unos 10 minutos a ambas bandejas. No uses harina de mesa, azúcar para rebozar ni glaseado. Mantén la segunda bandeja en frío mientras se hornea la primera.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "Galletas de jengibre y melaza: Aplana sin añadir cobertura"}, {"title": "Hornea una bandeja por tanda", "content": "Hornea la primera bandeja en la zona media unos 12 minutos a 175 °C; revisa a los 10. Los bordes deben verse firmes y algo más oscuros, y el centro debe estar cuajado, sin masa húmeda. Saca con guantes y hornea la segunda otros 12 minutos; reserva unos 3 minutos para cambiar bandejas. Se proponen 24 minutos de horno y 27 de esta etapa completa. Si siguen crudas, prolonga y suma el tiempo: el aspecto de la foto no valida la cocción.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "Galletas de jengibre y melaza: Hornea una bandeja por tanda"}, {"title": "Enfría por completo", "content": "Deja cada tanda unos 5 minutos en su bandeja y pasa con espátula a la rejilla otros 20 minutos, hasta que esté fría. El enfriado de la primera tanda se solapa con el segundo horneado; después de la última salida cuenta 25 minutos completos. No cierres el recipiente con las galletas calientes. El tiempo propuesto hasta terminar el frío es de 157 minutos, con tareas solapadas; añade cualquier enfriado o cocción extra.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "Galletas de jengibre y melaza: Enfría por completo"}, {"title": "Sirve y guarda", "content": "Dedica unos 2 minutos a repartir las 24 galletas sin decoración ni acompañamientos incluidos. Se proponen 159 minutos completos y una galleta por ración nutricional; cantidades, tiempos y rendimiento pendientes de confirmación en cocina. Una vez frías, guarda en recipiente limpio bien cerrado, en lugar fresco y seco; consumir en 48 horas es una propuesta de calidad no ensayada, no vida útil validada. No guardes piezas húmedas o mal cocidas ni establezcas seguridad por el olor.", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "Galletas de jengibre y melaza: Sirve y guarda"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy (abril de 2018)", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "harina de trigo común, sin levadura incorporada", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "jengibre molido seco", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "canela molida", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "bicarbonato sódico alimentario", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "sal fina", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "mantequilla sin sal", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "azúcar moreno", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "melaza de caña para uso alimentario", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "huevo entero batido, peso sin cáscara", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "Una galleta; 24 unidades propuestas", "method": "Suma de gramos comestibles por valores USDA por 100 g, dividida entre 24. Nueve alimentos exactos y ocho nutrientes informados en todos; no se inventan datos ausentes.", "note": "Estimación pendiente de confirmación, no análisis ni prueba de cocina. Los 644 g son ingredientes iniciales y unos 26,8 g por porción cruda, no rendimiento horneado medido. Melaza y azúcar moreno genéricos, no una marca exacta; huevo pesado sin cáscara, especias secas. Incluye toda la harina, mantequilla, bicarbonato y sal, sin harina de mesa, azúcar de cobertura ni glaseado. No se inventan pérdidas por evaporación o manipulación. Cambiar productos o número de unidades cambia valores."}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "Galletas redondas tostadas de jengibre y melaza, sin glaseado ni azúcar exterior, con una pieza partida que muestra el interior cocido"}], "published": false, "editorial_status": "draft", "keywords": ["galletas de jengibre", "galletas con melaza", "galletas redondas sin glaseado"], "notes": "Propuesta original de galletas redondas de jengibre seco y melaza, sin glaseado ni azúcar exterior. Contiene trigo, huevo y leche de la mantequilla; revisa etiquetas y trazas. No sustituye directamente melaza por miel, jarabe o melaza negra concentrada: cambia sabor, humedad y composición. El jengibre fresco tampoco equivale al molido seco. Cambiar harina, grasa o huevo requiere adaptar y recalcular; no garantiza un resultado equivalente ni aptitud para alergias. Toda la harina va en la masa, sin enharinar la mesa; todo el bicarbonato y la sal se cuentan. Los pesos iniciales no son rendimiento horneado medido. Harina y huevo crudos pueden contener patógenos: no pruebes la masa, no la ofrezcas para jugar y limpia manos, utensilios y superficies tras manipularla. No se propone tratar harina en casa para comerla cruda. Enfría masa a 4 °C o menos y conserva el huevo refrigerado hasta usarlo. Hornea hasta que el centro esté cuajado; amplía el tiempo real si es preciso. Los 48 horas de conservación propuestos son una sugerencia de calidad sin ensayo, no una vida útil validada. No se fija congelación ni se afirma prueba de cocina o beneficio de salud.", "seo": {"title": "Galletas de jengibre y melaza paso a paso", "description": "Galletas redondas de jengibre: cantidades para 24 unidades propuestas, masa refrigerada, horneado en dos tandas y conservación explicada.", "image_alt": "Galletas redondas tostadas de jengibre y melaza, sin glaseado ni azúcar exterior, con una pieza partida que muestra el interior cocido", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "¿Puedo sustituir la melaza por miel?", "a": "No como cambio directo con el mismo resultado. La melaza aporta sabor, color y humedad distintos; usar miel, jarabe o melaza muy concentrada exige adaptar cantidades y revisar el cálculo. Esta propuesta calcula melaza de caña genérica USDA."}, {"q": "¿Por qué enfriar y por qué no añadir más harina?", "a": "El frío permite manejar la masa sin incorporar harina de mesa. Se proponen 60 minutos a 4 °C o menos; amplía si aún no está firme. Más harina altera la proporción y la textura. Nunca pruebes la masa cruda: el frío no elimina los riesgos de harina y huevo."}, {"q": "¿Cuántas salen y cuánto tardan?", "a": "Se proponen 24 galletas redondas de unos 26,8 g de masa inicial y 159 minutos completos, con dos tandas de horno y enfriado incluidos. No es rendimiento confirmado ni peso final medido. Si cambia el tamaño o tu horno, ajusta la cocción real y el total; guardar 48 horas en seco es una propuesta de calidad no ensayada."}]}, "content_html": "<p>Galletas redondas propuestas de jengibre seco, canela y melaza, sin glaseado. Se reparte toda la masa en 24 porciones y se incluyen frío, dos tandas de horno y enfriado: 159 minutos propuestos, pendientes de confirmación en cocina.</p><p>Propuesta original de galletas redondas de jengibre seco y melaza, sin glaseado ni azúcar exterior. Contiene trigo, huevo y leche de la mantequilla; revisa etiquetas y trazas. No sustituye directamente melaza por miel, jarabe o melaza negra concentrada: cambia sabor, humedad y composición. El jengibre fresco tampoco equivale al molido seco. Cambiar harina, grasa o huevo requiere adaptar y recalcular; no garantiza un resultado equivalente ni aptitud para alergias. Toda la harina va en la masa, sin enharinar la mesa; todo el bicarbonato y la sal se cuentan. Los pesos iniciales no son rendimiento horneado medido. Harina y huevo crudos pueden contener patógenos: no pruebes la masa, no la ofrezcas para jugar y limpia manos, utensilios y superficies tras manipularla. No se propone tratar harina en casa para comerla cruda. Enfría masa a 4 °C o menos y conserva el huevo refrigerado hasta usarlo. Hornea hasta que el centro esté cuajado; amplía el tiempo real si es preciso. Los 48 horas de conservación propuestos son una sugerencia de calidad sin ensayo, no una vida útil validada. No se fija congelación ni se afirma prueba de cocina o beneficio de salud.</p>"}, {"id": "1005d609-dfd0-589f-94b3-92d2d9c114ab", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "ingwerkekse-rezept", "public_path": "/de/ingwerkekse-rezept", "source_url": null, "language": "de", "title": "Runde Ingwer-Melasse-Kekse", "excerpt": "Ingwer-Melasse-Kekse ohne Glasur mit abgewogenen Zutaten, gekühltem Teig und zwei Backdurchgängen für vorgeschlagene 24 Stück.", "summary": "Vorgeschlagene runde Kekse mit gemahlenem Ingwer, Zimt und Melasse, ohne Glasur. Den gesamten Teig in 24 Portionen teilen; Kühlung, zwei Backdurchgänge und Auskühlen sind in den vorgeschlagenen 159 Minuten enthalten. Eine Küchenprüfung steht aus.", "category": "Desserts", "category_slug": "postres", "difficulty": "Mittel", "course": "Dessert", "cuisine": "Europäisch inspiriert", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "gewöhnliches Weizenmehl ohne zugesetzte Triebmittel", "amount": "300", "unit": "g", "group": "Trockene Zutaten"}, {"name": "getrockneter gemahlener Ingwer", "amount": "6", "unit": "g", "group": "Trockene Zutaten"}, {"name": "gemahlener Zimt", "amount": "3", "unit": "g", "group": "Trockene Zutaten"}, {"name": "Natron in Lebensmittelqualität", "amount": "3", "unit": "g", "group": "Trockene Zutaten"}, {"name": "feines Salz", "amount": "2", "unit": "g", "group": "Trockene Zutaten"}, {"name": "ungesalzene Butter", "amount": "100", "unit": "g", "group": "Feuchte Zutaten"}, {"name": "brauner Zucker", "amount": "80", "unit": "g", "group": "Feuchte Zutaten"}, {"name": "Zuckerrohrmelasse in Lebensmittelqualität", "amount": "100", "unit": "g", "group": "Feuchte Zutaten"}, {"name": "verquirltes Vollei, ohne Schale abgewogen", "amount": "50", "unit": "g", "group": "Feuchte Zutaten"}], "steps": [{"title": "Abwiegen und vorbereiten", "content": "Hände waschen und Waage, zwei etwa 40 × 30 cm große Bleche mit Backpapier, Handrührgerät, Teigschaber und Gitter bereitlegen. 300 g Mehl, 6 g Ingwer, 3 g Zimt, 3 g Natron, 2 g Salz, 100 g Butter, 80 g braunen Zucker und 100 g Melasse abwiegen. Das Ei in einer Schüssel verquirlen und 50 g ohne Schale abwiegen. Die Butter etwa 20 Minuten weich werden lassen, bis sie auf Druck nachgibt, ohne zu schmelzen; etwa 10 dieser Minuten zum Abwiegen und Vorbereiten nutzen. Das Ei bis zur Verwendung kühlen. Rohes Mehl und rohen Teig niemals probieren.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Abwiegen und vorbereiten"}, {"title": "Feuchte Zutaten verrühren", "content": "Weiche Butter mit braunem Zucker schlagen, bis keine großen Klumpen bleiben. Abgewogene Melasse und Ei zugeben, vermischen und bei ausgeschaltetem Gerät die Schüssel ausschaben, bis alles verbunden ist. Insgesamt etwa 5 Minuten einplanen. Keinen Honig, kein Wasser, keine Vanille und kein zusätzliches Ei zufügen: Rezept und Berechnung enthalten nur die abgewogenen Zutaten.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Feuchte Zutaten verrühren"}, {"title": "Trockene Zutaten einarbeiten", "content": "Das gesamte Mehl mit Ingwer, Zimt, Natron und Salz separat vermischen und Klumpen auflösen. Mit dem Teigschaber in die feuchte Mischung einarbeiten, bis kein trockenes Mehl sichtbar bleibt; nicht lange kneten. Etwa 5 Minuten einplanen. Der Teig ist klebrig; kein zusätzliches Mehl zugeben. Bleibt loses Mehl, weiter ausschaben und einarbeiten; Mengenänderungen erfordern eine neue Berechnung.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Trockene Zutaten einarbeiten"}, {"title": "Portionieren und kühlen", "content": "Den gesamten Teig in etwa 5 Minuten in 24 gleich große Portionen teilen; die anfänglichen 644 g entsprechen vor dem Backen etwa 26,8 g je Portion, keinem gemessenen Endgewicht. Mit sauberen Händen Kugeln formen, in einen Behälter legen, abdecken und bei höchstens 4 °C für 60 Minuten fest werden lassen. Den Ofen während der letzten 15 Minuten der Kühlung auf 175 °C Ober-/Unterhitze vorheizen. Bei längerer Kühlung die tatsächliche Zusatzzeit einrechnen.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Portionieren und kühlen"}, {"title": "Ohne Überzug flach drücken", "content": "Je 12 Kugeln in einem Raster von 4 × 3 auf jedes Blech legen. Zwischen kleinen Backpapierstücken mit einem flachen Boden zu etwa 6 cm breiten und 1 cm dicken Scheiben drücken; etwa 3 cm Abstand zwischen den Rändern lassen und das obere Papier entfernen. Etwa 10 Minuten für beide Bleche einplanen. Kein Mehl zum Bestäuben, keinen Zuckerüberzug und keine Glasur verwenden. Das zweite Blech kühlen, während das erste backt.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Ohne Überzug flach drücken"}, {"title": "Ein Blech nach dem anderen backen", "content": "Das erste Blech auf mittlerer Schiene etwa 12 Minuten bei 175 °C backen; nach 10 prüfen. Die Ränder sollen fest und etwas dunkler sein, die Mitte durchgebacken, ohne feuchten Teig. Mit Ofenhandschuhen herausnehmen und das zweite Blech weitere 12 Minuten backen; etwa 3 Minuten zum Blechwechsel einplanen. Vorgesehen sind 24 Minuten Backzeit und 27 Minuten für die gesamte Phase. Bei rohem Inneren länger backen und die Zeit addieren: Ein Foto bestätigt keine sichere Garung.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Ein Blech nach dem anderen backen"}, {"title": "Vollständig auskühlen lassen", "content": "Jede Portion etwa 5 Minuten auf dem Blech lassen, dann mit einem Pfannenwender für weitere 20 Minuten auf das Gitter setzen, bis sie kalt ist. Das erste Auskühlen überschneidet sich mit dem zweiten Backdurchgang; nach dem letzten Herausnehmen volle 25 Minuten einplanen. Den Behälter nicht mit warmen Keksen verschließen. Bis zum Ende des Auskühlens sind 157 Minuten mit überlappenden Aufgaben vorgesehen; zusätzliche Kühl- oder Backzeit addieren.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Vollständig auskühlen lassen"}, {"title": "Servieren und aufbewahren", "content": "Etwa 2 Minuten einplanen, um die 24 Kekse ohne Dekoration oder eingerechnete Beilagen zu verteilen. Vorgesehen sind insgesamt 159 Minuten und ein Keks als Nährwertportion; Mengen, Zeiten und Ausbeute müssen noch in der Küche bestätigt werden. Kalt in einem sauberen, dicht verschlossenen Behälter kühl und trocken aufbewahren; Verzehr innerhalb von 48 Stunden ist ein ungeprüfter Qualitätsvorschlag, keine validierte Haltbarkeit. Keine feuchten oder unzureichend gebackenen Stücke lagern und Sicherheit nicht am Geruch beurteilen.", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "Runde Ingwer-Melasse-Kekse: Servieren und aufbewahren"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "gewöhnliches Weizenmehl ohne zugesetzte Triebmittel", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "getrockneter gemahlener Ingwer", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "gemahlener Zimt", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "Natron in Lebensmittelqualität", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "feines Salz", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "ungesalzene Butter", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "brauner Zucker", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "Zuckerrohrmelasse in Lebensmittelqualität", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "verquirltes Vollei, ohne Schale abgewogen", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "Ein Keks; vorgeschlagene 24 Stück", "method": "Summe der essbaren Gramm mal USDA-Werte pro 100 g, geteilt durch 24. Neun genaue Lebensmittel und acht bei allen angegebene Nährstoffe; fehlende Daten werden nicht erfunden.", "note": "Schätzung mit ausstehender Bestätigung, keine Analyse oder Küchenprüfung. 644 g Anfangszutaten und etwa 26,8 g je rohe Portion sind keine gemessene gebackene Ausbeute. Generische Melasse und brauner Zucker, keine genaue Marke; Ei ohne Schale abgewogen, getrocknete Gewürze. Sämtliches Mehl, Butter, Natron und Salz sind enthalten, ohne Bestäubungsmehl, Zuckerüberzug oder Glasur. Keine erfundenen Verdunstungs- oder Handhabungsverluste. Andere Produkte oder Stückzahlen verändern die Werte."}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "Runde gebräunte Ingwer-Melasse-Kekse ohne Glasur oder Zuckerüberzug, mit einem aufgebrochenen Stück und durchgebackenem Inneren"}], "published": false, "editorial_status": "draft", "keywords": ["Ingwerkekse", "Melassekekse", "runde Kekse ohne Glasur"], "notes": "Eigene Rezeptvorschläge für runde Kekse mit getrocknetem Ingwer und Melasse, ohne Glasur oder äußeren Zucker. Enthält Weizen, Ei und Milch aus Butter; Etiketten und Spurenhinweise prüfen. Honig, Sirup oder stark konzentrierte Melasse sind kein direkter Austausch: Geschmack, Feuchtigkeit und Zusammensetzung ändern sich. Frischer Ingwer entspricht nicht getrocknetem gemahlenem Ingwer. Änderungen bei Mehl, Fett oder Ei erfordern Anpassung und Neuberechnung; keine Ergebnisgleichheit oder Allergieeignung ist zugesichert. Das gesamte Mehl kommt in den Teig, ohne die Arbeitsfläche zu bestäuben; Natron und Salz sind vollständig eingerechnet. Anfangsgewichte sind keine gemessene gebackene Ausbeute. Rohes Mehl und Ei können Krankheitserreger enthalten: Teig nicht probieren oder zum Spielen anbieten; Hände, Geräte und Flächen danach reinigen. Eine häusliche Mehlbehandlung zum Rohverzehr ist nicht vorgesehen. Teig bei höchstens 4 °C kühlen, Ei bis zur Verwendung gekühlt halten. Bis zur festen Mitte backen, bei Bedarf die tatsächliche Zeit verlängern. Die vorgeschlagenen 48 Stunden Lagerung sind ein ungeprüfter Qualitätshinweis, keine validierte Haltbarkeit. Keine Gefrierdauer, Küchenprüfung oder gesundheitliche Wirkung wird behauptet.", "seo": {"title": "Ingwer-Melasse-Kekse Schritt für Schritt", "description": "Runde Ingwerkekse: Mengen für vorgeschlagene 24 Stück, gekühlter Teig, zwei Backdurchgänge und Hinweise zur Aufbewahrung.", "image_alt": "Runde gebräunte Ingwer-Melasse-Kekse ohne Glasur oder Zuckerüberzug, mit einem aufgebrochenen Stück und durchgebackenem Inneren", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "Kann ich Melasse durch Honig ersetzen?", "a": "Nicht direkt bei identischem Ergebnis. Melasse hat einen anderen Geschmack, eine andere Farbe und Feuchtigkeit; Honig, Sirup oder hochkonzentrierte Melasse erfordern angepasste Mengen und eine neue Berechnung. Dieser Vorschlag verwendet generische USDA-Zuckerrohrmelasse."}, {"q": "Warum kühlen statt mehr Mehl zuzugeben?", "a": "Kälte macht den Teig ohne Mehl zum Bestäuben handhabbar. Vorgesehen sind 60 Minuten bei höchstens 4 °C; bei weichem Teig verlängern. Mehr Mehl verändert Verhältnis und Textur. Rohen Teig niemals probieren: Kühlung beseitigt die Risiken von rohem Mehl und Ei nicht."}, {"q": "Wie viele Kekse und wie viel Zeit?", "a": "Vorgesehen sind 24 runde Kekse aus jeweils etwa 26,8 g Anfangsteig und insgesamt 159 Minuten einschließlich zweier Backdurchgänge und Auskühlen. Das ist keine bestätigte Ausbeute oder gemessenes Endgewicht. Bei anderen Größen oder Öfen tatsächliche Back- und Gesamtzeit anpassen; 48 Stunden trockene Lagerung sind ein ungeprüfter Qualitätsvorschlag."}]}, "content_html": "<p>Vorgeschlagene runde Kekse mit gemahlenem Ingwer, Zimt und Melasse, ohne Glasur. Den gesamten Teig in 24 Portionen teilen; Kühlung, zwei Backdurchgänge und Auskühlen sind in den vorgeschlagenen 159 Minuten enthalten. Eine Küchenprüfung steht aus.</p><p>Eigene Rezeptvorschläge für runde Kekse mit getrocknetem Ingwer und Melasse, ohne Glasur oder äußeren Zucker. Enthält Weizen, Ei und Milch aus Butter; Etiketten und Spurenhinweise prüfen. Honig, Sirup oder stark konzentrierte Melasse sind kein direkter Austausch: Geschmack, Feuchtigkeit und Zusammensetzung ändern sich. Frischer Ingwer entspricht nicht getrocknetem gemahlenem Ingwer. Änderungen bei Mehl, Fett oder Ei erfordern Anpassung und Neuberechnung; keine Ergebnisgleichheit oder Allergieeignung ist zugesichert. Das gesamte Mehl kommt in den Teig, ohne die Arbeitsfläche zu bestäuben; Natron und Salz sind vollständig eingerechnet. Anfangsgewichte sind keine gemessene gebackene Ausbeute. Rohes Mehl und Ei können Krankheitserreger enthalten: Teig nicht probieren oder zum Spielen anbieten; Hände, Geräte und Flächen danach reinigen. Eine häusliche Mehlbehandlung zum Rohverzehr ist nicht vorgesehen. Teig bei höchstens 4 °C kühlen, Ei bis zur Verwendung gekühlt halten. Bis zur festen Mitte backen, bei Bedarf die tatsächliche Zeit verlängern. Die vorgeschlagenen 48 Stunden Lagerung sind ein ungeprüfter Qualitätshinweis, keine validierte Haltbarkeit. Keine Gefrierdauer, Küchenprüfung oder gesundheitliche Wirkung wird behauptet.</p>"}, {"id": "f07f4ef1-1098-5542-9b78-5c22f05617f3", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "gingerbread-cookies-recipe", "public_path": "/en/gingerbread-cookies-recipe", "source_url": null, "language": "en", "title": "Round ginger and molasses cookies", "excerpt": "Plain ginger and molasses cookies with weighed ingredients, chilled dough and two oven batches for 24 proposed cookies.", "summary": "Proposed round cookies with ground ginger, cinnamon and molasses, without icing. Divide all the dough into 24 portions; chilling, two oven batches and cooling are included in the proposed 159 minutes, pending kitchen confirmation.", "category": "Desserts", "category_slug": "postres", "difficulty": "Medium", "course": "Dessert", "cuisine": "European-inspired", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "plain all-purpose wheat flour, without added raising agents", "amount": "300", "unit": "g", "group": "Dry ingredients"}, {"name": "ground dried ginger", "amount": "6", "unit": "g", "group": "Dry ingredients"}, {"name": "ground cinnamon", "amount": "3", "unit": "g", "group": "Dry ingredients"}, {"name": "food-grade baking soda", "amount": "3", "unit": "g", "group": "Dry ingredients"}, {"name": "fine salt", "amount": "2", "unit": "g", "group": "Dry ingredients"}, {"name": "unsalted butter", "amount": "100", "unit": "g", "group": "Wet ingredients"}, {"name": "brown sugar", "amount": "80", "unit": "g", "group": "Wet ingredients"}, {"name": "food-grade cane molasses", "amount": "100", "unit": "g", "group": "Wet ingredients"}, {"name": "beaten whole egg, weighed without shell", "amount": "50", "unit": "g", "group": "Wet ingredients"}], "steps": [{"title": "Weigh and organize", "content": "Wash your hands and prepare scales, two baking sheets about 40 × 30 cm lined with baking parchment, a mixer, spatula and cooling rack. Weigh 300 g flour, 6 g ginger, 3 g cinnamon, 3 g baking soda, 2 g salt, 100 g butter, 80 g brown sugar and 100 g molasses. Beat the egg in a bowl and weigh 50 g without shell. Leave the butter for about 20 minutes until it yields to pressure without melting; use about 10 of those minutes for weighing and organizing. Keep the egg refrigerated until needed. Never taste raw flour or dough.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "Round ginger and molasses cookies: Weigh and organize"}, {"title": "Mix the wet ingredients", "content": "Beat the softened butter and brown sugar until there are no large lumps. Add the weighed molasses and egg, mix and scrape with the mixer switched off until combined. Allow about 5 minutes in total. Do not add honey, water, vanilla or more egg: this formula and calculation include only the weighed ingredients.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "Round ginger and molasses cookies: Mix the wet ingredients"}, {"title": "Combine the dry ingredients and dough", "content": "Separately combine all the flour, ginger, cinnamon, baking soda and salt, breaking up lumps. Fold into the wet mixture with a spatula until no dry flour remains, without prolonged kneading. Allow about 5 minutes. The dough will be sticky; do not add extra flour. If loose flour remains, scrape and keep combining; any quantity change requires recalculation.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "Round ginger and molasses cookies: Combine the dry ingredients and dough"}, {"title": "Divide and chill", "content": "Divide all the dough into 24 equal portions in about 5 minutes; the initial 644 g correspond to about 26.8 g per portion before baking, not a measured final weight. With clean hands, form balls, place in a container, cover and refrigerate at 4 °C or below for 60 minutes, until firm. Preheat the conventional oven to 175 °C during the final 15 minutes of chilling. If more chilling is needed, add the actual time.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "Round ginger and molasses cookies: Divide and chill"}, {"title": "Flatten without a coating", "content": "Put 12 balls on each baking sheet in a 4 × 3 grid. Flatten between small pieces of baking parchment with a flat base into discs about 6 cm wide and 1 cm thick; leave about 3 cm between edges and remove the top paper. Allow about 10 minutes for both sheets. Use no dusting flour, coating sugar or icing. Keep the second sheet refrigerated while the first bakes.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "Round ginger and molasses cookies: Flatten without a coating"}, {"title": "Bake one sheet at a time", "content": "Bake the first sheet on the middle rack for about 12 minutes at 175 °C; check at 10. The edges should look firm and slightly darker, with a set center and no wet dough. Remove with oven mitts and bake the second sheet for another 12 minutes; allow about 3 minutes to change sheets. The proposed oven time is 24 minutes and the whole stage 27 minutes. If still raw, bake longer and add the time: a photograph cannot validate doneness.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "Round ginger and molasses cookies: Bake one sheet at a time"}, {"title": "Cool completely", "content": "Leave each batch on its sheet for about 5 minutes, then transfer with a spatula to the rack for another 20 minutes, until cold. Cooling the first batch overlaps baking the second; allow a full 25 minutes after the last sheet comes out. Do not close the container while the cookies are hot. The proposed time through the end of cooling is 157 minutes, including overlapping tasks; add any extra cooling or baking.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "Round ginger and molasses cookies: Cool completely"}, {"title": "Serve and store", "content": "Allow about 2 minutes to share out the 24 cookies without decorations or included accompaniments. The proposed full time is 159 minutes, with one cookie as the nutritional serving; quantities, times and yield await kitchen confirmation. Once cold, keep in a clean tightly closed container in a cool, dry place; eating within 48 hours is an untested quality proposal, not a validated shelf life. Do not store damp or underbaked cookies or judge safety by smell.", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "Round ginger and molasses cookies: Serve and store"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "plain all-purpose wheat flour, without added raising agents", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "ground dried ginger", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "ground cinnamon", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "food-grade baking soda", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "fine salt", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "unsalted butter", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "brown sugar", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "food-grade cane molasses", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "beaten whole egg, weighed without shell", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "One cookie; 24 proposed cookies", "method": "Sum edible grams multiplied by USDA values per 100 g, divided by 24. Nine exact foods and eight nutrients reported for every food; missing data are never invented.", "note": "Estimate pending confirmation, not laboratory analysis or a kitchen test. The 644 g are initial ingredients and about 26.8 g per raw portion, not measured baked yield. Generic molasses and brown sugar, not a specific brand; egg weighed without shell and dried spices. Includes all flour, butter, baking soda and salt, without dusting flour, coating sugar or icing. No invented evaporation or handling losses. Changing products or cookie count changes values."}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "Plain browned round ginger and molasses cookies without icing or sugar coating, with a broken cookie showing its baked interior"}], "published": false, "editorial_status": "draft", "keywords": ["ginger cookies", "molasses cookies", "plain round cookies"], "notes": "Original proposal for round cookies with dried ginger and molasses, without icing or sugar coating. Contains wheat, egg and milk from butter; check labels and cross-contact statements. Honey, syrup or concentrated blackstrap molasses are not direct equivalents: flavor, moisture and composition change. Fresh ginger is not equivalent to dried ground ginger. Changing flour, fat or egg requires adaptation and recalculation, without promising equivalent results or allergy suitability. All flour goes into the dough without dusting the worktop; all baking soda and salt are counted. Initial weights are not measured baked yield. Raw flour and egg can carry pathogens: do not taste the dough or offer it for play; clean hands, utensils and surfaces after handling. Home flour treatment for raw eating is not proposed. Chill dough at 4 °C or below and keep egg refrigerated until use. Bake until the center is set, extending actual time if needed. The proposed 48 hours of storage is an untested quality suggestion, not validated shelf life. No freezing period, kitchen test or health benefit is claimed.", "seo": {"title": "Ginger and molasses cookies, step by step", "description": "Round ginger cookies: weighed ingredients for 24 proposed cookies, chilled dough, two oven batches and explained storage.", "image_alt": "Plain browned round ginger and molasses cookies without icing or sugar coating, with a broken cookie showing its baked interior", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "Can I replace the molasses with honey?", "a": "Not as a direct swap with an identical result. Molasses has different flavor, color and moisture; honey, syrup or highly concentrated molasses require adapted quantities and recalculation. This proposal calculates generic USDA cane molasses."}, {"q": "Why chill the dough rather than add more flour?", "a": "Chilling makes the dough easier to handle without dusting flour. The proposal is 60 minutes at 4 °C or below; extend it if still soft. Extra flour changes the ratio and texture. Never taste raw dough: chilling does not remove raw flour and egg risks."}, {"q": "How many cookies and how much time?", "a": "The proposal is 24 round cookies from about 26.8 g initial dough each and 159 full minutes, including two oven batches and cooling. It is neither confirmed yield nor measured final weight. If size or oven conditions differ, adjust actual baking and total time; 48 hours of dry storage is an untested quality proposal."}]}, "content_html": "<p>Proposed round cookies with ground ginger, cinnamon and molasses, without icing. Divide all the dough into 24 portions; chilling, two oven batches and cooling are included in the proposed 159 minutes, pending kitchen confirmation.</p><p>Original proposal for round cookies with dried ginger and molasses, without icing or sugar coating. Contains wheat, egg and milk from butter; check labels and cross-contact statements. Honey, syrup or concentrated blackstrap molasses are not direct equivalents: flavor, moisture and composition change. Fresh ginger is not equivalent to dried ground ginger. Changing flour, fat or egg requires adaptation and recalculation, without promising equivalent results or allergy suitability. All flour goes into the dough without dusting the worktop; all baking soda and salt are counted. Initial weights are not measured baked yield. Raw flour and egg can carry pathogens: do not taste the dough or offer it for play; clean hands, utensils and surfaces after handling. Home flour treatment for raw eating is not proposed. Chill dough at 4 °C or below and keep egg refrigerated until use. Bake until the center is set, extending actual time if needed. The proposed 48 hours of storage is an untested quality suggestion, not validated shelf life. No freezing period, kitchen test or health benefit is claimed.</p>"}, {"id": "378b38d6-e9e8-52fd-b0ea-f357f002e533", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "biscuits-au-gingembre", "public_path": "/fr/biscuits-au-gingembre", "source_url": null, "language": "fr", "title": "Biscuits ronds au gingembre et à la mélasse", "excerpt": "Biscuits sans glaçage, au gingembre sec et à la mélasse, avec pâte refroidie et deux fournées pour 24 pièces proposées.", "summary": "Proposition de biscuits ronds au gingembre moulu, à la cannelle et à la mélasse, sans glaçage. Toute la pâte est répartie en 24 portions ; repos au froid, deux fournées et refroidissement sont inclus dans les 159 minutes proposées, à confirmer en cuisine.", "category": "Desserts", "category_slug": "postres", "difficulty": "Moyenne", "course": "Dessert", "cuisine": "Inspiration européenne", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "farine de blé courante, sans levure incorporée", "amount": "300", "unit": "g", "group": "Ingrédients secs"}, {"name": "gingembre séché moulu", "amount": "6", "unit": "g", "group": "Ingrédients secs"}, {"name": "cannelle moulue", "amount": "3", "unit": "g", "group": "Ingrédients secs"}, {"name": "bicarbonate de sodium alimentaire", "amount": "3", "unit": "g", "group": "Ingrédients secs"}, {"name": "sel fin", "amount": "2", "unit": "g", "group": "Ingrédients secs"}, {"name": "beurre doux", "amount": "100", "unit": "g", "group": "Ingrédients humides"}, {"name": "sucre brun", "amount": "80", "unit": "g", "group": "Ingrédients humides"}, {"name": "mélasse de canne alimentaire", "amount": "100", "unit": "g", "group": "Ingrédients humides"}, {"name": "œuf entier battu, pesé sans coquille", "amount": "50", "unit": "g", "group": "Ingrédients humides"}], "steps": [{"title": "Peser et organiser", "content": "Lavez-vous les mains et préparez une balance, deux plaques d’environ 40 × 30 cm couvertes de papier cuisson, un batteur, une spatule et une grille. Pesez 300 g de farine, 6 g de gingembre, 3 g de cannelle, 3 g de bicarbonate, 2 g de sel, 100 g de beurre, 80 g de sucre brun et 100 g de mélasse. Battez l’œuf dans un bol et pesez 50 g sans coquille. Laissez le beurre s’assouplir environ 20 minutes, jusqu’à céder à la pression sans fondre ; utilisez environ 10 de ces minutes pour peser et préparer. Gardez l’œuf au frais jusqu’à utilisation. Ne goûtez jamais farine ou pâte crues.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Peser et organiser"}, {"title": "Battre les ingrédients humides", "content": "Battez le beurre souple avec le sucre brun jusqu’à disparition des gros grumeaux. Ajoutez la mélasse et l’œuf pesés ; mélangez et raclez le bol, batteur éteint, jusqu’à homogénéité. Prévoyez environ 5 minutes au total. N’ajoutez ni miel, ni eau, ni vanille, ni œuf supplémentaire : cette formule et son calcul incluent uniquement les ingrédients pesés.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Battre les ingrédients humides"}, {"title": "Incorporer les ingrédients secs", "content": "Mélangez séparément toute la farine, le gingembre, la cannelle, le bicarbonate et le sel, en défaisant les grumeaux. Incorporez aux ingrédients humides à la spatule jusqu’à disparition de la farine sèche, sans pétrir longtemps. Prévoyez environ 5 minutes. La pâte est collante ; n’ajoutez pas de farine. S’il en reste non incorporée, raclez et continuez à mélanger ; toute modification de quantité impose de revoir le calcul.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Incorporer les ingrédients secs"}, {"title": "Diviser et refroidir", "content": "Divisez toute la pâte en 24 portions égales en environ 5 minutes ; les 644 g initiaux correspondent à environ 26,8 g par portion avant cuisson, pas à un poids final mesuré. Formez des boules avec les mains propres, placez-les dans un récipient, couvrez et réfrigérez à 4 °C ou moins pendant 60 minutes, jusqu’à fermeté. Préchauffez le four à 175 °C en chaleur traditionnelle pendant les dernières 15 minutes de ce repos. Si le froid doit durer davantage, ajoutez le temps réel.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Diviser et refroidir"}, {"title": "Aplatir sans enrobage", "content": "Placez 12 boules sur chaque plaque, en grille de 4 × 3. Aplatissez entre de petits morceaux de papier cuisson avec une base plate, en disques d’environ 6 cm de diamètre et 1 cm d’épaisseur ; laissez environ 3 cm entre les bords et retirez le papier supérieur. Prévoyez environ 10 minutes pour les deux plaques. N’utilisez ni farine de travail, ni sucre d’enrobage, ni glaçage. Gardez la seconde plaque au frais pendant la première cuisson.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Aplatir sans enrobage"}, {"title": "Cuire une plaque à la fois", "content": "Cuisez la première plaque à mi-hauteur environ 12 minutes à 175 °C ; vérifiez à 10. Les bords doivent être fermes et légèrement plus foncés, le centre pris, sans pâte humide. Sortez avec des gants et cuisez la seconde encore 12 minutes ; comptez environ 3 minutes pour changer les plaques. On propose 24 minutes de cuisson et 27 minutes pour toute cette étape. Si l’intérieur reste cru, prolongez et ajoutez le temps : une photo ne valide pas la cuisson.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Cuire une plaque à la fois"}, {"title": "Laisser refroidir complètement", "content": "Laissez chaque fournée environ 5 minutes sur sa plaque, puis transférez à la spatule sur la grille pour encore 20 minutes, jusqu’à refroidissement. Le refroidissement de la première fournée chevauche la seconde cuisson ; après la dernière sortie, comptez 25 minutes complètes. Ne fermez pas le récipient tant que les biscuits sont chauds. Le temps proposé jusqu’à la fin du refroidissement est de 157 minutes, avec tâches chevauchées ; ajoutez toute cuisson ou attente supplémentaire.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Laisser refroidir complètement"}, {"title": "Servir et conserver", "content": "Prévoyez environ 2 minutes pour répartir les 24 biscuits sans décoration ni accompagnement inclus. On propose 159 minutes complètes et un biscuit par portion nutritionnelle ; quantités, temps et rendement restent à confirmer en cuisine. Une fois froids, conservez dans un récipient propre bien fermé, au frais et au sec ; les manger sous 48 heures est une proposition de qualité non testée, pas une durée de conservation validée. Ne stockez pas de biscuits humides ou mal cuits et ne jugez pas la sécurité à l’odeur.", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "Biscuits ronds au gingembre et à la mélasse: Servir et conserver"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "farine de blé courante, sans levure incorporée", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "gingembre séché moulu", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "cannelle moulue", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "bicarbonate de sodium alimentaire", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "sel fin", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "beurre doux", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "sucre brun", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "mélasse de canne alimentaire", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "œuf entier battu, pesé sans coquille", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "Un biscuit ; 24 unités proposées", "method": "Somme des grammes comestibles multipliés par les valeurs USDA pour 100 g, divisée par 24. Neuf aliments exacts et huit nutriments indiqués pour chacun ; aucune donnée absente inventée.", "note": "Estimation à confirmer, pas une analyse ni un essai en cuisine. Les 644 g sont les ingrédients initiaux et environ 26,8 g par portion crue, pas le rendement cuit mesuré. Mélasse et sucre brun génériques, sans marque exacte ; œuf pesé sans coquille et épices sèches. Toute farine, beurre, bicarbonate et sel sont inclus, sans farine de travail, sucre extérieur ni glaçage. Aucune perte d’évaporation ou de manipulation inventée. Produits ou nombre d’unités différents changent les valeurs."}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "Biscuits ronds brunis au gingembre et à la mélasse, sans glaçage ni enrobage sucré, avec un biscuit cassé montrant son intérieur cuit"}], "published": false, "editorial_status": "draft", "keywords": ["biscuits au gingembre", "biscuits à la mélasse", "biscuits ronds sans glaçage"], "notes": "Proposition originale de biscuits ronds au gingembre sec et à la mélasse, sans glaçage ni sucre extérieur. Contient blé, œuf et lait du beurre ; vérifiez étiquettes et traces. Miel, sirop ou mélasse noire très concentrée ne sont pas des substitutions directes : goût, humidité et composition changent. Le gingembre frais n’équivaut pas au gingembre sec moulu. Changer farine, matière grasse ou œuf nécessite adaptation et nouveau calcul, sans garantie de résultat équivalent ni d’aptitude aux allergies. Toute la farine est dans la pâte, sans fariner le plan de travail ; tout le bicarbonate et le sel sont comptés. Les poids initiaux ne sont pas un rendement cuit mesuré. Farine et œuf crus peuvent contenir des agents pathogènes : ne goûtez pas la pâte et ne la proposez pas pour jouer ; nettoyez mains, ustensiles et surfaces ensuite. Aucun traitement domestique de farine pour consommation crue n’est proposé. Refroidissez la pâte à 4 °C ou moins et gardez l’œuf au frais jusqu’à emploi. Cuisez jusqu’à ce que le centre soit pris, en prolongeant au besoin le temps réel. Les 48 heures de conservation proposées sont une indication de qualité non testée, pas une durée validée. Aucune congélation, épreuve en cuisine ou propriété de santé n’est affirmée.", "seo": {"title": "Biscuits au gingembre et à la mélasse, pas à pas", "description": "Biscuits ronds au gingembre : quantités pour 24 pièces proposées, pâte refroidie, deux fournées et conservation expliquée.", "image_alt": "Biscuits ronds brunis au gingembre et à la mélasse, sans glaçage ni enrobage sucré, avec un biscuit cassé montrant son intérieur cuit", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "Puis-je remplacer la mélasse par du miel ?", "a": "Pas directement avec un résultat identique. La mélasse a un goût, une couleur et une humidité différents ; miel, sirop ou mélasse très concentrée nécessitent adaptation des quantités et du calcul. Cette proposition utilise une référence USDA générique de mélasse de canne."}, {"q": "Pourquoi refroidir plutôt qu’ajouter de la farine ?", "a": "Le froid permet de manipuler sans farine de travail. On propose 60 minutes à 4 °C ou moins ; prolongez si la pâte est encore molle. La farine supplémentaire change les proportions et la texture. Ne goûtez jamais la pâte crue : le froid ne supprime pas les risques de farine et d’œuf crus."}, {"q": "Combien de biscuits et combien de temps ?", "a": "On propose 24 biscuits ronds avec environ 26,8 g de pâte initiale chacun et 159 minutes complètes, deux fournées et refroidissement inclus. Ce n’est ni un rendement confirmé ni un poids final mesuré. Si taille ou four diffèrent, adaptez cuisson réelle et total ; 48 heures de stockage au sec restent une proposition de qualité non testée."}]}, "content_html": "<p>Proposition de biscuits ronds au gingembre moulu, à la cannelle et à la mélasse, sans glaçage. Toute la pâte est répartie en 24 portions ; repos au froid, deux fournées et refroidissement sont inclus dans les 159 minutes proposées, à confirmer en cuisine.</p><p>Proposition originale de biscuits ronds au gingembre sec et à la mélasse, sans glaçage ni sucre extérieur. Contient blé, œuf et lait du beurre ; vérifiez étiquettes et traces. Miel, sirop ou mélasse noire très concentrée ne sont pas des substitutions directes : goût, humidité et composition changent. Le gingembre frais n’équivaut pas au gingembre sec moulu. Changer farine, matière grasse ou œuf nécessite adaptation et nouveau calcul, sans garantie de résultat équivalent ni d’aptitude aux allergies. Toute la farine est dans la pâte, sans fariner le plan de travail ; tout le bicarbonate et le sel sont comptés. Les poids initiaux ne sont pas un rendement cuit mesuré. Farine et œuf crus peuvent contenir des agents pathogènes : ne goûtez pas la pâte et ne la proposez pas pour jouer ; nettoyez mains, ustensiles et surfaces ensuite. Aucun traitement domestique de farine pour consommation crue n’est proposé. Refroidissez la pâte à 4 °C ou moins et gardez l’œuf au frais jusqu’à emploi. Cuisez jusqu’à ce que le centre soit pris, en prolongeant au besoin le temps réel. Les 48 heures de conservation proposées sont une indication de qualité non testée, pas une durée validée. Aucune congélation, épreuve en cuisine ou propriété de santé n’est affirmée.</p>"}, {"id": "9ba749f2-3377-535b-a890-5025e20dfabc", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "ricetta-biscotti-di-pan-zenzero", "public_path": "/it/ricetta-biscotti-di-pan-zenzero", "source_url": "https://manualdecocina.com/it/ricetta-biscotti-di-pan-zenzero/", "language": "it", "title": "Biscotti rotondi allo zenzero e alla melassa", "excerpt": "Biscotti con zenzero secco e melassa, senza glassa, con impasto freddo e due infornate per 24 pezzi proposti.", "summary": "Proposta di biscotti rotondi con zenzero macinato, cannella e melassa, senza glassa. Tutto l’impasto si divide in 24 porzioni; riposo in frigorifero, due infornate e raffreddamento sono inclusi nei 159 minuti proposti, da confermare in cucina.", "category": "Dolci", "category_slug": "postres", "difficulty": "Media", "course": "Dessert", "cuisine": "Ispirazione europea", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "farina di frumento comune, senza lievito aggiunto", "amount": "300", "unit": "g", "group": "Ingredienti secchi"}, {"name": "zenzero secco macinato", "amount": "6", "unit": "g", "group": "Ingredienti secchi"}, {"name": "cannella macinata", "amount": "3", "unit": "g", "group": "Ingredienti secchi"}, {"name": "bicarbonato di sodio alimentare", "amount": "3", "unit": "g", "group": "Ingredienti secchi"}, {"name": "sale fino", "amount": "2", "unit": "g", "group": "Ingredienti secchi"}, {"name": "burro non salato", "amount": "100", "unit": "g", "group": "Ingredienti umidi"}, {"name": "zucchero bruno", "amount": "80", "unit": "g", "group": "Ingredienti umidi"}, {"name": "melassa di canna alimentare", "amount": "100", "unit": "g", "group": "Ingredienti umidi"}, {"name": "uovo intero sbattuto, pesato senza guscio", "amount": "50", "unit": "g", "group": "Ingredienti umidi"}], "steps": [{"title": "Pesare e organizzare", "content": "Lava le mani e prepara bilancia, due teglie di circa 40 × 30 cm con carta da forno, sbattitore, spatola e griglia. Pesa 300 g di farina, 6 g di zenzero, 3 g di cannella, 3 g di bicarbonato, 2 g di sale, 100 g di burro, 80 g di zucchero bruno e 100 g di melassa. Sbatti l’uovo in una ciotola e pesane 50 g senza guscio. Lascia ammorbidire il burro per circa 20 minuti, finché cede alla pressione senza sciogliersi; dedica circa 10 di quei minuti a pesare e organizzare. Tieni l’uovo in frigorifero fino all’uso. Non assaggiare farina o impasto crudi.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Pesare e organizzare"}, {"title": "Sbattere gli ingredienti umidi", "content": "Sbatti il burro morbido con lo zucchero bruno finché non restano grumi grandi. Aggiungi melassa e uovo pesati; mescola e raschia con lo sbattitore spento fino ad amalgamare. Dedica circa 5 minuti in totale. Non aggiungere miele, acqua, vaniglia o altro uovo: formula e calcolo includono solo gli ingredienti pesati.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Sbattere gli ingredienti umidi"}, {"title": "Unire gli ingredienti secchi", "content": "Mescola a parte tutta la farina, zenzero, cannella, bicarbonato e sale, eliminando i grumi. Incorpora agli ingredienti umidi con la spatola finché non è visibile farina asciutta, senza impastare a lungo. Dedica circa 5 minuti. L’impasto è appiccicoso; non correggere con altra farina. Se ne resta non incorporata, raschia e continua a mescolare; ogni modifica delle quantità richiede di rivedere il calcolo.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Unire gli ingredienti secchi"}, {"title": "Dividere e raffreddare", "content": "Dividi tutto l’impasto in 24 porzioni uguali in circa 5 minuti; i 644 g iniziali corrispondono a circa 26,8 g per porzione prima del forno, non a un peso finale misurato. Con mani pulite forma palline, mettile in un contenitore, copri e refrigera a 4 °C o meno per 60 minuti, finché sono sode. Preriscalda il forno statico a 175 °C negli ultimi 15 minuti del riposo. Se occorre altro freddo, aggiungi il tempo reale.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Dividere e raffreddare"}, {"title": "Appiattire senza copertura", "content": "Distribuisci 12 palline in ogni teglia, in una griglia di 4 × 3. Appiattisci fra piccoli pezzi di carta da forno con una base piatta fino a dischi di circa 6 cm di diametro e 1 cm di spessore; lascia circa 3 cm fra i bordi e togli la carta superiore. Dedica circa 10 minuti a entrambe le teglie. Non usare farina sul piano, zucchero da copertura o glassa. Tieni la seconda teglia in frigorifero mentre cuoce la prima.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Appiattire senza copertura"}, {"title": "Cuocere una teglia per volta", "content": "Cuoci la prima teglia nella zona centrale per circa 12 minuti a 175 °C; controlla a 10. I bordi devono essere sodi e leggermente più scuri, il centro cotto senza impasto umido. Estrai con guanti e cuoci la seconda per altri 12 minuti; prevedi circa 3 minuti per cambiare le teglie. Si propongono 24 minuti di forno e 27 per l’intera fase. Se restano crudi, prolunga e aggiungi il tempo: una foto non convalida la cottura.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Cuocere una teglia per volta"}, {"title": "Raffreddare completamente", "content": "Lascia ogni infornata sulla teglia per circa 5 minuti, poi trasferisci con la spatola sulla griglia per altri 20 minuti, fino a freddo. Il raffreddamento della prima si sovrappone alla seconda cottura; dopo l’ultima uscita conta 25 minuti completi. Non chiudere il contenitore con i biscotti caldi. Il tempo proposto fino al termine del raffreddamento è di 157 minuti con attività sovrapposte; aggiungi ogni cottura o attesa supplementare.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Raffreddare completamente"}, {"title": "Servire e conservare", "content": "Dedica circa 2 minuti a distribuire i 24 biscotti senza decorazioni né accompagnamenti inclusi. Si propongono 159 minuti complessivi e un biscotto per porzione nutrizionale; quantità, tempi e resa attendono conferma in cucina. Freddi, conservali in un contenitore pulito ben chiuso, al fresco e all’asciutto; consumarli entro 48 ore è una proposta di qualità non provata, non una durata validata. Non conservare pezzi umidi o poco cotti e non giudicare la sicurezza dall’odore.", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "Biscotti rotondi allo zenzero e alla melassa: Servire e conservare"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "farina di frumento comune, senza lievito aggiunto", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "zenzero secco macinato", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "cannella macinata", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "bicarbonato di sodio alimentare", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "sale fino", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "burro non salato", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "zucchero bruno", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "melassa di canna alimentare", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "uovo intero sbattuto, pesato senza guscio", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "Un biscotto; 24 pezzi proposti", "method": "Somma dei grammi commestibili moltiplicati per i valori USDA per 100 g, divisa per 24. Nove alimenti esatti e otto nutrienti riportati per tutti; nessun dato mancante inventato.", "note": "Stima da confermare, non analisi o prova in cucina. I 644 g sono ingredienti iniziali e circa 26,8 g per porzione cruda, non resa cotta misurata. Melassa e zucchero bruno generici, non una marca esatta; uovo pesato senza guscio e spezie secche. Tutta farina, burro, bicarbonato e sale inclusi, senza farina sul piano, zucchero esterno o glassa. Nessuna perdita per evaporazione o manipolazione inventata. Prodotti o numero di pezzi diversi modificano i valori."}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "Biscotti rotondi dorati allo zenzero e melassa, senza glassa o zucchero esterno, con un pezzo spezzato che mostra l’interno cotto"}], "published": false, "editorial_status": "draft", "keywords": ["biscotti allo zenzero", "biscotti alla melassa", "biscotti rotondi senza glassa"], "notes": "Proposta originale di biscotti rotondi con zenzero secco e melassa, senza glassa o zucchero esterno. Contiene frumento, uovo e latte del burro; controlla etichette e tracce. Miele, sciroppo o melassa nera molto concentrata non sono sostituti diretti: cambiano sapore, umidità e composizione. Lo zenzero fresco non equivale a quello secco macinato. Cambiare farina, grasso o uovo richiede adattamento e ricalcolo, senza garantire risultato equivalente o idoneità alle allergie. Tutta la farina va nell’impasto, senza infarinare il piano; bicarbonato e sale sono interamente conteggiati. I pesi iniziali non sono resa cotta misurata. Farina e uovo crudi possono contenere patogeni: non assaggiare l’impasto né offrirlo per giocare; pulisci mani, attrezzi e superfici dopo la manipolazione. Non si propone trattamento domestico della farina per consumo crudo. Raffredda l’impasto a 4 °C o meno e conserva l’uovo in frigorifero fino all’uso. Cuoci finché il centro è rassodato, prolungando se necessario il tempo reale. Le 48 ore di conservazione proposte sono un suggerimento di qualità non provato, non una durata validata. Non si stabilisce congelamento né si afferma prova in cucina o beneficio salutistico.", "seo": {"title": "Biscotti allo zenzero e melassa passo per passo", "description": "Biscotti rotondi allo zenzero: dosi per 24 pezzi proposti, impasto refrigerato, due infornate e conservazione spiegata.", "image_alt": "Biscotti rotondi dorati allo zenzero e melassa, senza glassa o zucchero esterno, con un pezzo spezzato che mostra l’interno cotto", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "Posso sostituire la melassa con miele?", "a": "Non direttamente con risultato identico. Melassa, miele e sciroppi differiscono per sapore, colore e umidità; altri prodotti o melassa molto concentrata richiedono quantità adattate e nuovo calcolo. Questa proposta usa il riferimento USDA generico per melassa di canna."}, {"q": "Perché raffreddare invece di aggiungere farina?", "a": "Il freddo consente di maneggiare senza farina sul piano. Si propongono 60 minuti a 4 °C o meno; prolunga se l’impasto è ancora morbido. Altra farina cambia rapporti e consistenza. Non assaggiare mai impasto crudo: il freddo non elimina i rischi di farina e uovo crudi."}, {"q": "Quanti biscotti e quanto tempo?", "a": "Si propongono 24 biscotti rotondi da circa 26,8 g di impasto iniziale ciascuno e 159 minuti completi, comprese due infornate e raffreddamento. Non è resa confermata né peso finale misurato. Se cambiano dimensione o forno, adatta cottura reale e totale; 48 ore di conservazione asciutta sono una proposta di qualità non provata."}]}, "content_html": "<p>Proposta di biscotti rotondi con zenzero macinato, cannella e melassa, senza glassa. Tutto l’impasto si divide in 24 porzioni; riposo in frigorifero, due infornate e raffreddamento sono inclusi nei 159 minuti proposti, da confermare in cucina.</p><p>Proposta originale di biscotti rotondi con zenzero secco e melassa, senza glassa o zucchero esterno. Contiene frumento, uovo e latte del burro; controlla etichette e tracce. Miele, sciroppo o melassa nera molto concentrata non sono sostituti diretti: cambiano sapore, umidità e composizione. Lo zenzero fresco non equivale a quello secco macinato. Cambiare farina, grasso o uovo richiede adattamento e ricalcolo, senza garantire risultato equivalente o idoneità alle allergie. Tutta la farina va nell’impasto, senza infarinare il piano; bicarbonato e sale sono interamente conteggiati. I pesi iniziali non sono resa cotta misurata. Farina e uovo crudi possono contenere patogeni: non assaggiare l’impasto né offrirlo per giocare; pulisci mani, attrezzi e superfici dopo la manipolazione. Non si propone trattamento domestico della farina per consumo crudo. Raffredda l’impasto a 4 °C o meno e conserva l’uovo in frigorifero fino all’uso. Cuoci finché il centro è rassodato, prolungando se necessario il tempo reale. Le 48 ore di conservazione proposte sono un suggerimento di qualità non provato, non una durata validata. Non si stabilisce congelamento né si afferma prova in cucina o beneficio salutistico.</p>"}, {"id": "8d5f73dc-183e-565b-b105-00279a6bbe45", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "ジンジャークッキー", "public_path": "/ja/ジンジャークッキー", "source_url": null, "language": "ja", "title": "丸いジンジャー・モラセスクッキー", "excerpt": "乾燥しょうがとモラセスを使う、アイシングなしのクッキー。材料を計量し、生地を冷やして二回に分けて焼く24枚の提案です。", "summary": "しょうが粉、シナモン、モラセスで作る丸いクッキーの提案です。アイシングは付けません。生地全量を24個に分け、冷蔵、二回の焼成、冷却を含めて159分を予定しています。分量、時間、出来上がりは調理確認待ちです。", "category": "デザート", "category_slug": "postres", "difficulty": "中級", "course": "デザート", "cuisine": "ヨーロッパ風", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "膨張剤入りではない一般的な小麦粉", "amount": "300", "unit": "g", "group": "粉類"}, {"name": "乾燥しょうが粉", "amount": "6", "unit": "g", "group": "粉類"}, {"name": "シナモンパウダー", "amount": "3", "unit": "g", "group": "粉類"}, {"name": "食用重曹", "amount": "3", "unit": "g", "group": "粉類"}, {"name": "細かい塩", "amount": "2", "unit": "g", "group": "粉類"}, {"name": "無塩バター", "amount": "100", "unit": "g", "group": "液体・油脂類"}, {"name": "ブラウンシュガー", "amount": "80", "unit": "g", "group": "液体・油脂類"}, {"name": "食用のサトウキビ由来モラセス", "amount": "100", "unit": "g", "group": "液体・油脂類"}, {"name": "溶いた全卵、殻を除いて計量", "amount": "50", "unit": "g", "group": "液体・油脂類"}], "steps": [{"title": "材料を量って準備する", "content": "手を洗い、はかり、約40 × 30 cmの天板二枚とオーブンペーパー、ハンドミキサー、へら、冷却用網を用意します。小麦粉300 g、しょうが6 g、シナモン3 g、重曹3 g、塩2 g、バター100 g、ブラウンシュガー80 g、モラセス100 gを量ります。別の器で卵を溶き、殻を除いた50 gを量ります。バターは約20分置き、押すとへこむが溶けていない状態にします。そのうち約10分で計量と準備を行います。卵は使うまで冷蔵します。生の小麦粉や生地を味見しないでください。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 材料を量って準備する"}, {"title": "液体・油脂類を混ぜる", "content": "柔らかくしたバターとブラウンシュガーを、大きな塊がなくなるまで混ぜます。量ったモラセスと卵を加えて混ぜ、ミキサーを止めて器の内側をへらで集め、均一にします。全体で約5分を予定します。はちみつ、水、バニラ、追加の卵は加えません。配合と計算に含むのは計量した材料だけです。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 液体・油脂類を混ぜる"}, {"title": "粉類を合わせて生地にする", "content": "小麦粉全量、しょうが、シナモン、重曹、塩を別に混ぜ、塊をほぐします。液体・油脂類にへらで混ぜ込み、乾いた粉が見えなくなるまで合わせます。長くこねません。約5分を予定します。粘りのある生地ですが、小麦粉を追加しないでください。粉が残る場合は器の内側を集め、混ぜ続けます。量を変更するときは計算も見直します。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 粉類を合わせて生地にする"}, {"title": "分割して冷やす", "content": "生地全量を約5分で24等分します。材料の初期合計644 gから、焼く前は一個約26.8 gとなる計算であり、出来上がり重量の実測値ではありません。清潔な手で丸めて容器に入れ、ふたをし、4 °C以下で60分、しっかりするまで冷蔵します。この冷蔵時間の最後の15分で、上下加熱のオーブンを175 °Cに予熱します。さらに冷却が必要なら実際の追加時間を加えます。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 分割して冷やす"}, {"title": "表面に何も付けず平らにする", "content": "各天板に12個ずつ、4 × 3の配置で並べます。小さなオーブンペーパーで上下を挟み、底の平らな道具で直径約6 cm、厚さ1 cmの円盤に押します。縁同士を約3 cm離し、上の紙を取り除きます。両天板で約10分を予定します。打ち粉、まぶす砂糖、アイシングは使いません。先の天板を焼く間、後の天板は冷蔵します。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 表面に何も付けず平らにする"}, {"title": "天板を一枚ずつ焼く", "content": "先の天板を中段で175 °C、約12分焼き、10分で確認します。縁が固まり少し濃い色になり、中心に湿った生地が残らない状態にします。ミトンを使って取り出し、後の天板をさらに12分焼きます。天板の入れ替えに約3分を予定します。焼成は計24分、この工程全体は27分の提案です。中が生なら焼成を延長して時間を加えます。写真の見た目で加熱の安全性は確認できません。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 天板を一枚ずつ焼く"}, {"title": "完全に冷ます", "content": "各回のクッキーを天板で約5分置き、へらで網へ移してさらに20分、冷たくなるまで冷まします。先の回の冷却は後の回の焼成と並行します。最後の天板を取り出した後は25分を丸ごと数えます。温かいまま容器を閉めないでください。並行作業を含め、冷却完了まで157分を予定します。焼成や冷却の延長時間は追加します。", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 完全に冷ます"}, {"title": "盛り分けて保存する", "content": "約2分で24枚を盛り分けます。飾りや付け合わせは計算に含みません。総時間159分、一枚を栄養計算の一食分とする提案で、分量、時間、出来上がりは調理確認待ちです。冷めてから清潔な密閉容器に入れ、涼しく乾いた場所で保存します。48時間以内に食べるという案は未試験の品質上の提案であり、検証済みの保存期限ではありません。湿ったものや焼き足りないものを保存せず、においで安全を判断しないでください。", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "丸いジンジャー・モラセスクッキー: 盛り分けて保存する"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "膨張剤入りではない一般的な小麦粉", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "乾燥しょうが粉", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "シナモンパウダー", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "食用重曹", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "細かい塩", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "無塩バター", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "ブラウンシュガー", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "食用のサトウキビ由来モラセス", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "溶いた全卵、殻を除いて計量", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "一枚。出来上がり24枚の提案", "method": "可食部の重量にUSDAの100 g当たりの値を掛けて合計し、24で割ります。九つの該当食品と、全食品に値がある八栄養項目を使用し、欠測値は作りません。", "note": "確認待ちの推計であり、分析や調理試験ではありません。644 gは材料の初期重量、一個約26.8 gは生地の計算値で、焼成後の出来上がりを実測した値ではありません。モラセスとブラウンシュガーは一般値で、特定銘柄ではありません。卵は殻なしで量り、香辛料は乾燥品を使います。小麦粉、バター、重曹、塩の全量を含み、打ち粉、表面の砂糖、アイシングは含みません。蒸発や作業損失の値は作りません。製品や枚数の変更で値も変わります。"}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "アイシングや砂糖の表面コーティングがない、焼き色の付いた丸いジンジャー・モラセスクッキー。割った一枚に焼けた内側が見える"}], "published": false, "editorial_status": "draft", "keywords": ["ジンジャークッキー", "モラセスクッキー", "丸いクッキー"], "notes": "乾燥しょうがとモラセスで作る丸いクッキーの独自提案で、アイシングや表面の砂糖はありません。小麦、卵、バター由来の乳を含みます。表示と混入に関する注意書きを確認してください。はちみつ、シロップ、濃縮度の高いブラックストラップ・モラセスは直接の代用品ではなく、風味、水分、成分が変わります。生のしょうがは乾燥しょうが粉と同等ではありません。小麦粉、油脂、卵の変更には配合調整と再計算が必要で、同じ仕上がりやアレルギーへの適合を保証しません。小麦粉全量を生地に使い、打ち粉を加えません。重曹と塩も全量を計算します。初期重量は焼成後の出来上がりの実測値ではありません。生の小麦粉や卵には病原体の可能性があります。生地を味見したり遊びに使ったりせず、扱った後に手、器具、作業面を洗浄します。生食用に小麦粉を家庭で処理する提案ではありません。生地を4 °C以下で冷やし、卵は使用まで冷蔵します。中心が固まるまで焼き、必要なら実際の時間を延長します。保存48時間という案は未試験の品質上の目安で、検証済み期限ではありません。冷凍期間、調理試験、健康上の効果は主張しません。", "seo": {"title": "しょうがとモラセスの丸いクッキーの作り方", "description": "ジンジャークッキー24枚の提案。材料の計量、冷蔵した生地、二回の焼成、冷却と保存を工程別に説明します。", "image_alt": "アイシングや砂糖の表面コーティングがない、焼き色の付いた丸いジンジャー・モラセスクッキー。割った一枚に焼けた内側が見える", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "モラセスをはちみつに替えられますか。", "a": "同じ結果を保つ直接置換ではありません。モラセスとは風味、色、水分が異なり、はちみつ、シロップ、濃縮モラセスを使う場合は量の調整と再計算が必要です。この提案はUSDAの一般的なサトウキビ由来モラセスの値を使います。"}, {"q": "なぜ小麦粉を足さずに冷やすのですか。", "a": "冷やすと打ち粉なしで扱いやすくなります。4 °C以下で60分を予定し、まだ柔らかければ延長します。追加の小麦粉は配合比と食感を変えます。生地を味見しないでください。冷却しても生の小麦粉や卵のリスクはなくなりません。"}, {"q": "何枚できて、どのくらいかかりますか。", "a": "初期生地一個約26.8 gの丸いクッキー24枚、二回の焼成と冷却を含め159分の提案です。確認済みの出来上がり個数や実測した最終重量ではありません。大きさやオーブンが変わる場合は実際の焼成時間と合計を調整します。乾いた状態で48時間保存する案も未試験の品質上の提案です。"}]}, "content_html": "<p>しょうが粉、シナモン、モラセスで作る丸いクッキーの提案です。アイシングは付けません。生地全量を24個に分け、冷蔵、二回の焼成、冷却を含めて159分を予定しています。分量、時間、出来上がりは調理確認待ちです。</p><p>乾燥しょうがとモラセスで作る丸いクッキーの独自提案で、アイシングや表面の砂糖はありません。小麦、卵、バター由来の乳を含みます。表示と混入に関する注意書きを確認してください。はちみつ、シロップ、濃縮度の高いブラックストラップ・モラセスは直接の代用品ではなく、風味、水分、成分が変わります。生のしょうがは乾燥しょうが粉と同等ではありません。小麦粉、油脂、卵の変更には配合調整と再計算が必要で、同じ仕上がりやアレルギーへの適合を保証しません。小麦粉全量を生地に使い、打ち粉を加えません。重曹と塩も全量を計算します。初期重量は焼成後の出来上がりの実測値ではありません。生の小麦粉や卵には病原体の可能性があります。生地を味見したり遊びに使ったりせず、扱った後に手、器具、作業面を洗浄します。生食用に小麦粉を家庭で処理する提案ではありません。生地を4 °C以下で冷やし、卵は使用まで冷蔵します。中心が固まるまで焼き、必要なら実際の時間を延長します。保存48時間という案は未試験の品質上の目安で、検証済み期限ではありません。冷凍期間、調理試験、健康上の効果は主張しません。</p>"}, {"id": "c571a0f8-637d-591c-9564-0484f22be53c", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "biscoitos-de-gengibre", "public_path": "/pt/biscoitos-de-gengibre", "source_url": null, "language": "pt", "title": "Biscoitos redondos de gengibre e melaço", "excerpt": "Biscoitos sem glacê, com gengibre seco e melaço, ingredientes pesados, massa refrigerada e duas fornadas para 24 unidades propostas.", "summary": "Proposta de biscoitos redondos com gengibre em pó, canela e melaço, sem glacê. Toda a massa é dividida em 24 porções; refrigeração, duas fornadas e resfriamento estão incluídos nos 159 minutos propostos, a confirmar em cozinha.", "category": "Sobremesas", "category_slug": "postres", "difficulty": "Média", "course": "Sobremesa", "cuisine": "Inspiração europeia", "prep_time_minutes": 37, "cook_time_minutes": 24, "total_time_minutes": 159, "servings": 24, "ingredients": [{"name": "farinha de trigo comum, sem fermento incorporado", "amount": "300", "unit": "g", "group": "Ingredientes secos"}, {"name": "gengibre seco em pó", "amount": "6", "unit": "g", "group": "Ingredientes secos"}, {"name": "canela em pó", "amount": "3", "unit": "g", "group": "Ingredientes secos"}, {"name": "bicarbonato de sódio alimentício", "amount": "3", "unit": "g", "group": "Ingredientes secos"}, {"name": "sal fino", "amount": "2", "unit": "g", "group": "Ingredientes secos"}, {"name": "manteiga sem sal", "amount": "100", "unit": "g", "group": "Ingredientes úmidos"}, {"name": "açúcar mascavo", "amount": "80", "unit": "g", "group": "Ingredientes úmidos"}, {"name": "melaço de cana próprio para alimentação", "amount": "100", "unit": "g", "group": "Ingredientes úmidos"}, {"name": "ovo inteiro batido, pesado sem casca", "amount": "50", "unit": "g", "group": "Ingredientes úmidos"}], "steps": [{"title": "Pese e organize", "content": "Lave as mãos e prepare balança, duas assadeiras de cerca de 40 × 30 cm com papel-manteiga próprio para forno, batedeira, espátula e grade. Pese 300 g de farinha, 6 g de gengibre, 3 g de canela, 3 g de bicarbonato, 2 g de sal, 100 g de manteiga, 80 g de açúcar mascavo e 100 g de melaço. Bata o ovo em uma tigela e pese 50 g sem casca. Deixe a manteiga amolecer por cerca de 20 minutos, até ceder à pressão sem derreter; use aproximadamente 10 desses minutos para pesar e organizar. Mantenha o ovo refrigerado até usar. Não prove farinha nem massa cruas.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-01.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Pese e organize"}, {"title": "Bata os ingredientes úmidos", "content": "Bata a manteiga macia com o açúcar mascavo até não restarem grumos grandes. Junte o melaço e o ovo pesados; misture e raspe a tigela com a batedeira desligada até incorporar. Reserve cerca de 5 minutos no total. Não acrescente mel, água, baunilha nem mais ovo: esta fórmula e seu cálculo incluem somente os ingredientes pesados.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-02.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Bata os ingredientes úmidos"}, {"title": "Incorpore os secos", "content": "Misture separadamente toda a farinha, gengibre, canela, bicarbonato e sal, desfazendo os grumos. Incorpore aos úmidos com espátula até não haver farinha seca visível, sem sovar por muito tempo. Reserve cerca de 5 minutos. A massa fica pegajosa; não corrija com farinha extra. Se houver farinha solta, raspe e continue incorporando; qualquer mudança de quantidade exige rever o cálculo.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-03.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Incorpore os secos"}, {"title": "Divida e refrigere", "content": "Divida toda a massa em 24 porções iguais em cerca de 5 minutos; os 644 g iniciais correspondem a aproximadamente 26,8 g por porção antes do forno, não a um peso final medido. Faça bolinhas com mãos limpas, coloque em um recipiente, tampe e refrigere a 4 °C ou menos por 60 minutos, até firmarem. Preaqueça o forno convencional a 175 °C nos últimos 15 minutos dessa refrigeração. Se precisar de mais frio, acrescente o tempo real.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-04.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Divida e refrigere"}, {"title": "Achate sem cobertura", "content": "Distribua 12 bolinhas em cada assadeira, em uma grade de 4 × 3. Achate entre pequenos pedaços de papel-manteiga com uma base plana até formar discos de cerca de 6 cm de diâmetro e 1 cm de espessura; deixe aproximadamente 3 cm entre as bordas e retire o papel de cima. Reserve cerca de 10 minutos para ambas as assadeiras. Não use farinha na bancada, açúcar para envolver nem glacê. Mantenha a segunda assadeira refrigerada enquanto a primeira assa.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-05.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Achate sem cobertura"}, {"title": "Asse uma assadeira por vez", "content": "Asse a primeira assadeira na posição central por cerca de 12 minutos a 175 °C; verifique aos 10. As bordas devem estar firmes e ligeiramente mais escuras, e o centro cozido, sem massa úmida. Retire com luvas e asse a segunda por mais 12 minutos; reserve aproximadamente 3 minutos para trocar as assadeiras. São propostos 24 minutos de forno e 27 para a etapa completa. Se ainda estiverem crus, prolongue e some o tempo: a aparência da foto não valida o cozimento.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-06.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Asse uma assadeira por vez"}, {"title": "Deixe esfriar completamente", "content": "Deixe cada fornada na assadeira por cerca de 5 minutos e passe com espátula para a grade por mais 20 minutos, até esfriar. O resfriamento da primeira fornada se sobrepõe ao segundo assamento; depois da última saída, conte 25 minutos completos. Não feche o recipiente com biscoitos quentes. O tempo proposto até terminar o resfriamento é de 157 minutos, com tarefas sobrepostas; acrescente qualquer cozimento ou resfriamento extra.", "image_url": "/recetas/receta-de-galletas-de-jengibre/paso-07.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Deixe esfriar completamente"}, {"title": "Sirva e guarde", "content": "Reserve cerca de 2 minutos para distribuir os 24 biscoitos sem decoração nem acompanhamentos incluídos. São propostos 159 minutos completos e um biscoito por porção nutricional; quantidades, tempos e rendimento aguardam confirmação em cozinha. Depois de frios, guarde em recipiente limpo bem fechado, em local fresco e seco; consumir em 48 horas é uma proposta de qualidade não testada, não um prazo de validade validado. Não guarde peças úmidas ou mal assadas nem determine segurança pelo cheiro.", "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "image_alt": "Biscoitos redondos de gengibre e melaço: Sirva e guarde"}], "nutrition": {"calories": 104.3, "protein_g": 1.6, "carbs_g": 16.2, "fat_g": 3.7, "saturated_fat_g": 2.2, "fiber_g": 0.4, "sugar_g": 6.4, "sodium_mg": 72.8, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "farinha de trigo comum, sem fermento incorporado", "edible_grams": 300, "fdc_id": 168936, "fdc_description": "Wheat flour, white, all-purpose, enriched, unbleached", "per_100g": {"calories": 364, "protein_g": 10.3, "carbs_g": 76.3, "fat_g": 0.98, "saturated_fat_g": 0.155, "fiber_g": 2.7, "sugar_g": 0.27, "sodium_mg": 2.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168936/nutrients"}, {"ingredient": "gengibre seco em pó", "edible_grams": 6, "fdc_id": 170926, "fdc_description": "Spices, ginger, ground", "per_100g": {"calories": 335, "protein_g": 8.98, "carbs_g": 71.6, "fat_g": 4.24, "saturated_fat_g": 2.6, "fiber_g": 14.1, "sugar_g": 3.39, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170926/nutrients"}, {"ingredient": "canela em pó", "edible_grams": 3, "fdc_id": 171320, "fdc_description": "Spices, cinnamon, ground", "per_100g": {"calories": 247, "protein_g": 3.99, "carbs_g": 80.6, "fat_g": 1.24, "saturated_fat_g": 0.345, "fiber_g": 53.1, "sugar_g": 2.17, "sodium_mg": 10.0}, "source_url": "https://fdc.nal.usda.gov/food-details/171320/nutrients"}, {"ingredient": "bicarbonato de sódio alimentício", "edible_grams": 3, "fdc_id": 175040, "fdc_description": "Leavening agents, baking soda", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 27400.0}, "source_url": "https://fdc.nal.usda.gov/food-details/175040/nutrients"}, {"ingredient": "sal fino", "edible_grams": 2, "fdc_id": 173468, "fdc_description": "Salt, table", "per_100g": {"calories": 0.0, "protein_g": 0.0, "carbs_g": 0.0, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 0.0, "sodium_mg": 38800.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"ingredient": "manteiga sem sal", "edible_grams": 100, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "açúcar mascavo", "edible_grams": 80, "fdc_id": 168833, "fdc_description": "Sugars, brown", "per_100g": {"calories": 380, "protein_g": 0.12, "carbs_g": 98.1, "fat_g": 0.0, "saturated_fat_g": 0.0, "fiber_g": 0.0, "sugar_g": 97.0, "sodium_mg": 28.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168833/nutrients"}, {"ingredient": "melaço de cana próprio para alimentação", "edible_grams": 100, "fdc_id": 168820, "fdc_description": "Molasses", "per_100g": {"calories": 290, "protein_g": 0.0, "carbs_g": 74.7, "fat_g": 0.1, "saturated_fat_g": 0.018, "fiber_g": 0.0, "sugar_g": 74.7, "sodium_mg": 37.0}, "source_url": "https://fdc.nal.usda.gov/food-details/168820/nutrients"}, {"ingredient": "ovo inteiro batido, pesado sem casca", "edible_grams": 50, "fdc_id": 171287, "fdc_description": "Egg, whole, raw, fresh", "per_100g": {"calories": 143, "protein_g": 12.6, "carbs_g": 0.72, "fat_g": 9.51, "saturated_fat_g": 3.13, "fiber_g": 0.0, "sugar_g": 0.37, "sodium_mg": 142}, "source_url": "https://fdc.nal.usda.gov/food-details/171287/nutrients"}], "serving_size": "Um biscoito; 24 unidades propostas", "method": "Soma dos gramas comestíveis multiplicados pelos valores USDA por 100 g, dividida por 24. Nove alimentos exatos e oito nutrientes informados em todos; dados ausentes nunca inventados.", "note": "Estimativa a confirmar, não análise nem teste em cozinha. Os 644 g são ingredientes iniciais e aproximadamente 26,8 g por porção crua, não rendimento assado medido. Melaço e açúcar mascavo genéricos, não uma marca exata; ovo pesado sem casca e especiarias secas. Toda farinha, manteiga, bicarbonato e sal incluídos, sem farinha na bancada, açúcar externo ou glacê. Não se inventam perdas por evaporação ou manuseio. Produtos ou número de unidades diferentes alteram os valores."}, "image_url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "gallery": [{"url": "/recetas/receta-de-galletas-de-jengibre/portada.webp", "alt": "Biscoitos redondos dourados de gengibre e melaço, sem glacê nem açúcar externo, com um biscoito partido mostrando o interior assado"}], "published": false, "editorial_status": "draft", "keywords": ["biscoitos de gengibre", "biscoitos com melaço", "biscoitos redondos sem glacê"], "notes": "Proposta original de biscoitos redondos com gengibre seco e melaço, sem glacê nem açúcar externo. Contém trigo, ovo e leite da manteiga; confira rótulos e avisos de traços. Mel, xarope ou melaço preto muito concentrado não substituem diretamente: sabor, umidade e composição mudam. Gengibre fresco não equivale ao seco em pó. Trocar farinha, gordura ou ovo exige adaptação e recálculo, sem garantir resultado equivalente ou adequação a alergias. Toda a farinha vai na massa, sem enfarinhar a bancada; todo o bicarbonato e sal são contabilizados. Os pesos iniciais não são rendimento assado medido. Farinha e ovo crus podem conter patógenos: não prove a massa nem ofereça para brincar; lave mãos, utensílios e superfícies após manusear. Não se propõe tratamento doméstico da farinha para consumo cru. Refrigere a massa a 4 °C ou menos e mantenha o ovo refrigerado até usar. Asse até o centro estar firme, prolongando o tempo real se necessário. As 48 horas de conservação propostas são uma sugestão de qualidade não testada, não uma validade comprovada. Não se estabelece congelamento nem se afirma teste em cozinha ou benefício de saúde.", "seo": {"title": "Biscoitos de gengibre e melaço passo a passo", "description": "Biscoitos redondos de gengibre: quantidades para 24 unidades propostas, massa refrigerada, duas fornadas e conservação explicada.", "image_alt": "Biscoitos redondos dourados de gengibre e melaço, sem glacê nem açúcar externo, com um biscoito partido mostrando o interior assado", "image_variants": ["/recetas/receta-de-galletas-de-jengibre/portada-1x1.webp", "/recetas/receta-de-galletas-de-jengibre/portada-4x3.webp", "/recetas/receta-de-galletas-de-jengibre/portada-16x9.webp"], "faq": [{"q": "Posso substituir o melaço por mel?", "a": "Não como troca direta com resultado idêntico. Melaço tem sabor, cor e umidade diferentes; mel, xarope ou melaço muito concentrado exigem quantidades adaptadas e novo cálculo. Esta proposta usa a referência USDA genérica de melaço de cana."}, {"q": "Por que refrigerar em vez de acrescentar farinha?", "a": "O frio permite manusear sem farinha na bancada. São propostos 60 minutos a 4 °C ou menos; prolongue se a massa ainda estiver mole. Farinha extra muda proporções e textura. Nunca prove massa crua: refrigeração não elimina os riscos de farinha e ovo crus."}, {"q": "Quantos biscoitos rende e quanto tempo leva?", "a": "São propostos 24 biscoitos redondos com aproximadamente 26,8 g de massa inicial cada e 159 minutos completos, incluindo duas fornadas e resfriamento. Não é rendimento confirmado nem peso final medido. Se tamanho ou forno mudar, ajuste cozimento real e total; guardar em seco por 48 horas é uma proposta de qualidade não testada."}]}, "content_html": "<p>Proposta de biscoitos redondos com gengibre em pó, canela e melaço, sem glacê. Toda a massa é dividida em 24 porções; refrigeração, duas fornadas e resfriamento estão incluídos nos 159 minutos propostos, a confirmar em cozinha.</p><p>Proposta original de biscoitos redondos com gengibre seco e melaço, sem glacê nem açúcar externo. Contém trigo, ovo e leite da manteiga; confira rótulos e avisos de traços. Mel, xarope ou melaço preto muito concentrado não substituem diretamente: sabor, umidade e composição mudam. Gengibre fresco não equivale ao seco em pó. Trocar farinha, gordura ou ovo exige adaptação e recálculo, sem garantir resultado equivalente ou adequação a alergias. Toda a farinha vai na massa, sem enfarinhar a bancada; todo o bicarbonato e sal são contabilizados. Os pesos iniciais não são rendimento assado medido. Farinha e ovo crus podem conter patógenos: não prove a massa nem ofereça para brincar; lave mãos, utensílios e superfícies após manusear. Não se propõe tratamento doméstico da farinha para consumo cru. Refrigere a massa a 4 °C ou menos e mantenha o ovo refrigerado até usar. Asse até o centro estar firme, prolongando o tempo real se necessário. As 48 horas de conservação propostas são uma sugestão de qualidade não testada, não uma validade comprovada. Não se estabelece congelamento nem se afirma teste em cozinha ou benefício de saúde.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id": "670af688-3058-4f8c-9070-96eaae0bda4f", "recipe_group_id": "adf06802-d942-42a6-a0fc-91a23c279198", "slug": "receta-de-galletas-de-jengibre", "public_path": "/receta-de-galletas-de-jengibre", "source_url": "https://manualdecocina.com/receta-de-galletas-de-jengibre/", "created_at": "2026-09-23T20:50:30.274106+00:00", "published_at": "2026-09-23T20:50:30.274106+00:00", "expected_row_md5": "0770444bd7cf5896a6dbf6155e185772"}$before$::jsonb;
 g constant uuid := 'adf06802-d942-42a6-a0fc-91a23c279198';
 outside_checksum text;
 es_count int;
 n int;
BEGIN
 IF current_setting('manualdecocina.batch04_gate',true) IS DISTINCT FROM 'ready15_deployed' THEN
  RAISE EXCEPTION 'Full15recipe lote04 publication/deployment gate not supplied';
 END IF;
 PERFORM id FROM public.recipes WHERE recipe_group_id=g ORDER BY id FOR UPDATE;
 IF jsonb_array_length(j)<>7 OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(j)x)<>7
  OR (SELECT count(DISTINCT x->>'language') FROM jsonb_array_elements(j)x)<>7
  OR (SELECT count(DISTINCT x->>'public_path') FROM jsonb_array_elements(j)x)<>7 THEN
  RAISE EXCEPTION 'Invalid gingercookies payload';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.recipe_group_id<>g OR r.language<>'es' OR r.slug<>b->>'slug' OR r.public_path<>b->>'public_path'
    OR r.source_url IS DISTINCT FROM b->>'source_url' OR r.created_at<>(b->>'created_at')::timestamptz
    OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Historical identity/date divergence before idempotent or initial publication';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j)x WHERE (x->>'recipe_group_id')::uuid<>g
    OR x->>'language' NOT IN ('es','de','en','fr','it','ja','pt')) THEN
  RAISE EXCEPTION 'Unexpected group or language in publication payload';
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)=7
  AND NOT EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR NOT r.published OR r.editorial_status<>'published' OR r.recipe_group_id<>x.recipe_group_id
